### Kokoro English TTS with speaker ID and WAV output

Source: https://github.com/k2-fsa/sherpa-onnx/blob/master/nodejs-addon-examples/test_tts_non_streaming_kokoro_en.js

Node.js sync API for offline TTS using a Kokoro English VITS model. Uses a kokoro config block with a voices.bin file. Speaker ID is set via sid: 6. Audio is generated and saved as WAV.

```javascript
const sherpa_onnx = require('sherpa-onnx-node');

function createOfflineTts() {
  const config = {
    model: {
      kokoro: {
        model: './kokoro-en-v0_19/model.onnx',
        voices: './kokoro-en-v0_19/voices.bin',
        tokens: './kokoro-en-v0_19/tokens.txt',
        dataDir: './kokoro-en-v0_19/espeak-ng-data',
      },
      debug: true,
      numThreads: 1,
      provider: 'cpu',
    },
    maxNumSentences: 1,
  };
  return new sherpa_onnx.OfflineTts(config);
}

const tts = createOfflineTts();

const text =
    'Today as always, men fall into two groups: slaves and free men. Whoever does not have two-thirds of his day for himself, is a slave, whatever he may be: a statesman, a businessman, an official, or a scholar.';

const generationConfig = new sherpa_onnx.GenerationConfig({
  sid: 6,
  speed: 1.0,
  silenceScale: 0.2,
});

const audio = tts.generate({text, generationConfig});

const filename = 'test-kokoro-en-6.wav';
sherpa_onnx.writeWave(
    filename, {samples: audio.samples, sampleRate: audio.sampleRate});

console.log(`Saved to ${filename}`);
```

